<template>
	<view class="editor-page">
		<view class="editor-nav"><text class="cuIcon-back" @tap="back"></text><text class="editor-nav-title">发布图集</text><text class="editor-publish" :class="{'disabled':!canSubmit}" @tap="submit">{{submitting?'提交中':'发布'}}</text></view>
		<scroll-view scroll-y class="editor-scroll">
			<view class="editor-form">
				<input v-model="title" maxlength="120" class="title-input" placeholder="给这组照片起个标题" />
				<textarea v-model="description" maxlength="2000" class="description-input" placeholder="分享照片背后的故事（选填）" />
				<view class="image-grid"><view class="image-cell" v-for="(item,index) in images" :key="item.url"><image :src="item.url" mode="aspectFill" @tap="preview(index)"/><text class="image-remove cuIcon-close" @tap.stop="removeImage(index)"></text><text class="cover-mark" v-if="index===0">封面</text></view><view v-if="images.length<9" class="image-add" @tap="chooseImages"><text class="cuIcon-cameraadd"></text><small>{{uploading?'正在上传':images.length+'/9'}}</small></view></view>
				<view class="form-section"><text class="section-title">添加标签</text><view class="tag-list"><text v-for="(tag,index) in tags" :key="tag" class="tag-token">#{{tag}} <text class="cuIcon-close" @tap="removeTag(index)"></text></text><input v-if="tags.length<10" v-model="tagInput" maxlength="24" placeholder="输入后回车添加" confirm-type="done" @confirm="addTag" @blur="addTag" /></view><view class="tag-hint">至少添加一个标签，最多10个</view></view>
				<view class="publish-note"><text class="cuIcon-info"></text><text>提交后由管理员审核，通过后会展示在图库中。</text></view>
			</view>
		</scroll-view>
	</view>
</template>

<script>
export default {data(){return {title:'',description:'',images:[],tags:[],tagInput:'',submitting:false,uploading:false}},computed:{canSubmit(){return this.title.trim().length>=2&&this.images.length>0&&this.tags.length>0&&!this.submitting&&!this.uploading}},methods:{token(){try{return JSON.parse(uni.getStorageSync('userinfo')||'{}').token||''}catch(e){return ''}},back(){uni.navigateBack({delta:1})},chooseImages(){if(this.uploading)return;const remaining=9-this.images.length;if(remaining<=0)return;uni.chooseImage({count:remaining,sizeType:['compressed'],sourceType:['album','camera'],success:async r=>{const paths=r.tempFilePaths||[];this.uploading=true;uni.showLoading({title:'上传图片'});for(let i=0;i<paths.length;i++){uni.showLoading({title:'上传 '+(i+1)+'/'+paths.length});const path=paths[i];const info=await new Promise(resolve=>uni.getImageInfo({src:path,success:resolve,fail:()=>resolve({width:4,height:5})}));const uploaded=await this.upload(path);if(uploaded)this.images.push({url:uploaded,ratio:Number(info.width||4)/Number(info.height||5)});else break}this.uploading=false;uni.hideLoading()}})},upload(path){return new Promise(resolve=>{uni.uploadFile({url:this.$API.upload(),filePath:path,name:'file',formData:{token:this.token()},success:r=>{try{const d=JSON.parse(r.data);resolve(d.code===1&&d.data&&d.data.url?d.data.url:'');if(!(d.code===1&&d.data&&d.data.url))uni.showToast({title:d.msg||'图片上传失败',icon:'none'})}catch(e){resolve('');uni.showToast({title:'上传响应无效',icon:'none'})}},fail:()=>{resolve('');uni.showToast({title:'图片上传失败',icon:'none'})}})})},preview(index){uni.previewImage({urls:this.images.map(x=>x.url),current:this.images[index].url})},removeImage(index){this.images.splice(index,1)},addTag(){const value=this.tagInput.trim().replace(/^[#＃]+/,'').replace(/[,，\s]/g,'');if(value&&!this.tags.includes(value)&&this.tags.length<10)this.tags.push(value);this.tagInput=''},removeTag(index){this.tags.splice(index,1)},submit(){this.addTag();if(!this.canSubmit)return;if(!this.token())return uni.navigateTo({url:'/pages/user/login'});this.submitting=true;this.$Net.request({url:this.$API.gallerySubmit(),data:{token:this.token(),params:JSON.stringify({title:this.title.trim(),description:this.description.trim(),imageUrls:this.images.map(x=>x.url),imageRatio:this.images[0]&&this.images[0].ratio||.8,tags:this.tags})},method:'post',dataType:'json',success:r=>{this.submitting=false;if(r.data&&r.data.code===1){uni.showModal({title:'图集已提交',content:'审核通过后会在图库公开展示。',showCancel:false,success:()=>this.back()})}else uni.showToast({title:r.data&&r.data.msg||'提交失败',icon:'none'})},fail:()=>{this.submitting=false;uni.showToast({title:'网络异常，请稍后重试',icon:'none'})}})}}}
</script>

<style scoped>
.editor-page{min-height:100vh;background:#f6f7f5;color:#202923}.editor-nav{height:calc(56px + env(safe-area-inset-top));padding:env(safe-area-inset-top) 18px 0;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #e8ece8}.editor-nav>.cuIcon-back{font-size:20px;width:42px}.editor-nav-title{font-size:16px;font-weight:650}.editor-publish{padding:8px 15px;border-radius:17px;background:#23826b;color:#fff;font-size:13px}.editor-publish.disabled{opacity:.4}.editor-scroll{height:calc(100vh - 56px - env(safe-area-inset-top))}.editor-form{max-width:760px;margin:0 auto;padding:23px 18px 60px}.title-input{width:100%;height:54px;border-bottom:1px solid #e3e8e3;font-size:21px;font-weight:650}.description-input{width:100%;min-height:92px;padding:16px 0;box-sizing:border-box;font-size:14px;line-height:1.65;color:#55635b}.image-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:15px}.image-cell,.image-add{position:relative;aspect-ratio:1;background:#e8ede9;border-radius:6px;overflow:hidden}.image-cell image{width:100%;height:100%}.image-remove{position:absolute;right:5px;top:5px;width:22px;height:22px;border-radius:50%;background:#15221dbb;color:#fff;text-align:center;line-height:22px;font-size:11px}.cover-mark{position:absolute;left:5px;bottom:5px;padding:3px 7px;background:#17231dc9;color:#fff;font-size:10px;border-radius:3px}.image-add{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:#7e8c83}.image-add>.cuIcon-cameraadd{font-size:24px}.image-add small{font-size:11px}.form-section{margin-top:28px}.section-title{font-size:14px;font-weight:650}.tag-list{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:13px}.tag-token{padding:7px 10px;background:#e8f0eb;color:#4d7764;border-radius:16px;font-size:12px}.tag-token .cuIcon-close{margin-left:4px}.tag-list input{min-width:130px;height:34px;font-size:12px}.tag-hint{margin-top:8px;color:#929d95;font-size:11px}.publish-note{display:flex;gap:8px;margin-top:30px;padding:13px 14px;background:#edf2ee;color:#77867d;border-radius:6px;font-size:11px;line-height:1.5}.publish-note>.cuIcon-info{color:#6c927d}.editor-publish:active{opacity:.8}@media(min-width:700px){.editor-form{padding-top:38px}.image-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}}
</style>
